-- Migration 022: Exercise pgvector Semantic Catalog
-- Enables pgvector, creates activity_groups with 768d vector embeddings,
-- links activity_types to activity_groups, and exposes match_activity_groups RPC.

CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE IF NOT EXISTS public.activity_groups (
  code text PRIMARY KEY,
  name text NOT NULL,
  category text NOT NULL,
  default_met numeric NOT NULL,
  search_keywords text[] DEFAULT '{}',
  embedding vector(768),
  is_active boolean DEFAULT true,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'activity_types' AND column_name = 'group_code'
  ) THEN
    ALTER TABLE public.activity_types ADD COLUMN group_code text REFERENCES public.activity_groups(code) ON DELETE SET NULL;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'activity_types' AND column_name = 'intensity_level'
  ) THEN
    ALTER TABLE public.activity_types ADD COLUMN intensity_level text DEFAULT 'moderate';
  END IF;
END $$;

ALTER TABLE public.activity_groups ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'activity_groups' AND policyname = 'Allow read activity_groups'
  ) THEN
    CREATE POLICY "Allow read activity_groups" ON public.activity_groups
      FOR SELECT TO authenticated, anon USING (true);
  END IF;
END $$;

GRANT SELECT ON public.activity_groups TO authenticated, anon;
GRANT ALL ON public.activity_groups TO service_role;

CREATE OR REPLACE FUNCTION public.match_activity_groups (
  query_embedding vector(768),
  match_threshold float DEFAULT 0.50,
  match_count int DEFAULT 5
)
RETURNS TABLE (
  code text,
  name text,
  category text,
  default_met numeric,
  similarity float
)
LANGUAGE sql STABLE AS $$
  SELECT
    activity_groups.code,
    activity_groups.name,
    activity_groups.category,
    activity_groups.default_met,
    ROUND((1 - (activity_groups.embedding <=> query_embedding))::numeric, 4)::float AS similarity
  FROM public.activity_groups
  WHERE activity_groups.is_active = true
    AND activity_groups.embedding IS NOT NULL
    AND (1 - (activity_groups.embedding <=> query_embedding)) > match_threshold
  ORDER BY similarity DESC
  LIMIT match_count;
$$;

GRANT EXECUTE ON FUNCTION public.match_activity_groups TO authenticated, anon, service_role;

